import{_ as a,c as o,o as r,ae as t}from"./chunks/framework.CHDT0Kbg.js";const c=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1795170900000}'),n={name:"guide/faq.md"};function i(s,e,d,h,l,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Quick answers about Persim.</p><h3 id="is-persim-free" tabindex="-1">Is Persim free? <a class="header-anchor" href="#is-persim-free" aria-label="Permalink to &quot;Is Persim free?&quot;">​</a></h3><p>You can download and use the core browsing features for free. Some advanced capabilities are unlocked with an in-app purchase, and the free version shows a small badge in the tab bar.</p><h3 id="which-operating-systems-are-supported" tabindex="-1">Which operating systems are supported? <a class="header-anchor" href="#which-operating-systems-are-supported" aria-label="Permalink to &quot;Which operating systems are supported?&quot;">​</a></h3><p>Persim is built for macOS 12 or later and runs on Apple Silicon and Intel Macs.</p><h3 id="will-my-data-be-uploaded" tabindex="-1">Will my data be uploaded? <a class="header-anchor" href="#will-my-data-be-uploaded" aria-label="Permalink to &quot;Will my data be uploaded?&quot;">​</a></h3><p>No account is required, and history, bookmarks, sessions and downloads stay on your Mac. Features that need the network — such as updating an ad-blocking subscription — fetch only what they need. You can remove site data from the cookie manager.</p><h3 id="how-do-i-import-bookmarks-from-another-browser" tabindex="-1">How do I import bookmarks from another browser? <a class="header-anchor" href="#how-do-i-import-bookmarks-from-another-browser" aria-label="Permalink to &quot;How do I import bookmarks from another browser?&quot;">​</a></h3><p>Export your bookmarks to an HTML file from Chrome or Edge, then use <strong>Import HTML</strong> in Persim&#39;s bookmark manager. Folders and duplicate links are handled for you.</p><h3 id="how-do-i-save-a-video-i-found-online" tabindex="-1">How do I save a video I found online? <a class="header-anchor" href="#how-do-i-save-a-video-i-found-online" aria-label="Permalink to &quot;How do I save a video I found online?&quot;">​</a></h3><p>Open the media panel, choose one of the detected videos and download it. Videos served in several pieces are joined into one MP4, and finished files can be opened with your usual apps.</p><h3 id="how-do-i-change-the-interface-language" tabindex="-1">How do I change the interface language? <a class="header-anchor" href="#how-do-i-change-the-interface-language" aria-label="Permalink to &quot;How do I change the interface language?&quot;">​</a></h3><p>Open <code>persim://settings</code> → <strong>General</strong> → <strong>Language</strong>. The app offers 25 languages; reopen the window to see the change.</p><h3 id="still-have-a-question" tabindex="-1">Still have a question? <a class="header-anchor" href="#still-have-a-question" aria-label="Permalink to &quot;Still have a question?&quot;">​</a></h3><p>Write to <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> and tell us what you were trying to do.</p>',16)])])}const m=a(n,[["render",i]]);export{c as __pageData,m as default};
